package orders

func TestPlaceRejectsEmpty(t *testing.T) {
	if Place(Order{}) == nil {
		t.Fatal("no error")
	}
}

func TestCheckRejectsMissing(t *testing.T) {
	if Check(Order{}) == nil {
		t.Fatal("no error")
	}
}

